fn vec_len<T>(x: &Vec<T>) -> usize {
    // Simply return the vector length
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    assert!(n > 0, "Input vector must be non-empty.");

    let mut result = Vec::with_capacity(n);
    let mut i = 0;

    // Iteration termination condition: i reaches n
    while i < n {
        // Push the element at index i from input to result.
        result.push(x[i]);
        i += 1;

        // At this point, result.len() == i (the number of elements processed)
        debug_assert_eq!(result.len(), i);
    }

    // The output vector length equals input vector length as required.
    debug_assert_eq!(result.len(), n);

    result
}